window.SLOKAM_TEXTS["kamasikashtakam"] = {
  revision: 2,
  verseWord: "श्लोकः", verseCount: 9, labels: {"0": "तनियन्", "10": "तनियन्"},
  order: [0, 1, 1, 2, 3, 4, 5, 6, 7, 8, 8, 9, 9, 10],
  lines: [
    {"v": 0, "text": "श्रीमान् वेङ्कटनाथार्यः कवितार्किककेसरी ।", "lat": "śrīmān vēṅkaṭanāthāryaḥ kavitārkikakēsarī |", "tam": "ஶ்ரீமாந் வேங்கடநாதா₂ர்ய: கவிதார்கிககேஸரீ ।"},
    {"v": 0, "text": "वेदान्ताचार्यवर्यो मे सन्निधत्तां सदा हृदि ॥", "lat": "vēdāntācāryavaryō mē sannidhattāṃ sadā hṛdi ||", "tam": "வேதா₃ந்தாசார்யவர்யோ மே ஸந்நித₄த்தாம் ஸதா₃ ஹ்ரு’தி₃ ॥"},
    {"v": 1, "text": "श्रुतीनामुत्तरं भागं वेगवत्याश्च दक्षिणम् ।", "lat": "śrutīnāmuttaraṃ bhāgaṃ vēgavatyāśca dakṣiṇam |", "tam": "ஶ்ருதீநாமுத்தரம் பா₄க₃ம் வேக₃வத்யாஶ்ச த₃க்ஷிணம் ।"},
    {"v": 1, "text": "कामादधिवसन् जीयात् कश्चिदद्भुतकेसरी ॥", "lat": "kāmādadhivasan jīyāt kaścidadbhutakēsarī ||", "tam": "காமாத₃தி₄வஸஞ்ஜீயாத் கஶ்சித₃த்₃பு₄தகேஸரீ ॥"},
    {"v": 2, "text": "तपनेन्द्वग्निनयनः तापानपचिनोतु नः ।", "lat": "tapanēndvagninayanaḥ tāpānapacinōtu naḥ |", "tam": "தபநேந்த்₃வக்₃நிநயந: தாபாநபசிநோது ந: ।"},
    {"v": 2, "text": "तापनीयरहस्यानां सारः कामासिकाहरिः ॥", "lat": "tāpanīyarahasyānāṃ sāraḥ kāmāsikāhariḥ ||", "tam": "தாபநீயரஹஸ்யாநாம் ஸார: காமாஸிகாஹரி: ॥"},
    {"v": 3, "text": "आकण्ठमादिपुरुषं", "lat": "ākaṇṭhamādipuruṣaṃ", "tam": "ஆகண்ட₂மாதி₃புருஷம்"},
    {"v": 3, "text": "कण्ठीरवमुपरि कुण्ठितारातिम् ।", "lat": "kaṇṭhīravamupari kuṇṭhitārātim |", "tam": "கண்டீ₂ரவமுபரி குண்டி₂தாராதிம் ।"},
    {"v": 3, "text": "वेगोपकण्ठसङ्गात्", "lat": "vēgōpakaṇṭhasaṅgāt", "tam": "வேகோ₃பகண்ட₂ஸங்கா₃த்"},
    {"v": 3, "text": "विमुक्तवैकुण्ठबहुमतिमुपासे ॥", "lat": "vimuktavaikuṇṭhabahumatimupāsē ||", "tam": "விமுக்தவைகுண்ட₂ப₃ஹுமதிமுபாஸே ॥"},
    {"v": 4, "text": "बन्धुमखिलस्य जन्तोः", "lat": "bandhumakhilasya jantōḥ", "tam": "ப₃ந்து₄மகி₂லஸ்ய ஜந்தோ:"},
    {"v": 4, "text": "बन्धुरपर्यङ्कबन्धरमणीयम् ।", "lat": "bandhuraparyaṅkabandharamaṇīyam |", "tam": "ப₃ந்து₄ரபர்யங்கப₃ந்த₄ரமணீயம் ।"},
    {"v": 4, "text": "विषमविलोचनमीडे", "lat": "viṣamavilōcanamīḍē", "tam": "விஷமவிலோசநமீடே₃"},
    {"v": 4, "text": "वेगवतीपुळिनकेळिनरसिंहम् ॥", "lat": "vēgavatīpuḻinakēḻinarasiṃham ||", "tam": "வேக₃வதீபுளிநகேளிநரஸிம்ஹம் ॥"},
    {"v": 5, "text": "स्वस्थानेषु मरुद्गणान् नियमयन् स्वाधीनसर्वेन्द्रियः", "lat": "svasthānēṣu marudgaṇān niyamayan svādhīnasarvēndriyaḥ", "tam": "ஸ்வஸ்தா₂நேஷு மருத்₃க₃ணாந் நியமயந் ஸ்வாதீ₄நஸர்வேந்த்₃ரிய:"},
    {"v": 5, "text": "पर्यङ्कस्थिरधारणाप्रकटितप्रत्यङ्मुखावस्थितिः ।", "lat": "paryaṅkasthiradhāraṇāprakaṭitapratyaṅmukhāvasthitiḥ |", "tam": "பர்யங்கஸ்தி₂ரதா₄ரணாப்ரகடிதப்ரத்யங்முகா₂வஸ்தி₂தி: ।"},
    {"v": 5, "text": "प्रायेण प्रणिपेदुषां प्रभुरसौ योगं निजं शिक्षयन्", "lat": "prāyēṇa praṇipēduṣāṃ prabhurasau yōgaṃ nijaṃ śikṣayan", "tam": "ப்ராயேண ப்ரணிபேது₃ஷாம் ப்ரபு₄ரஸௌ யோக₃ம் நிஜம் ஶிக்ஷயந்"},
    {"v": 5, "text": "कामानातनुतादशेषजगतां कामासिकाकेसरी ॥", "lat": "kāmānātanutādaśēṣajagatāṃ kāmāsikākēsarī ||", "tam": "காமாநாதநுதாத₃ஶேஷஜக₃தாம் காமாஸிகாகேஸரீ ॥"},
    {"v": 6, "text": "विकस्वरनखस्वरुक्षतहिरण्यवक्षःस्थली-", "lat": "vikasvaranakhasvarukṣatahiraṇyavakṣaḥsthalī-", "tam": "விகஸ்வரநக₂ஸ்வருக்ஷதஹிரண்யவக்ஷ:ஸ்த₂லீ-"},
    {"v": 6, "text": "निरर्गळविनिर्गळद्रुधिरसिन्धुसन्ध्यायिताः ।", "lat": "nirargaḻavinirgaḻadrudhirasindhusandhyāyitāḥ |", "tam": "நிரர்க₃ளவிநிர்க₃ளத்₃ருதி₄ரஸிந்து₄ஸந்த்₄யாயிதா: ।"},
    {"v": 6, "text": "अवन्तु मदनासिकामनुजपञ्चवक्त्रस्य माम्", "lat": "avantu madanāsikāmanujapañcavaktrasya mām", "tam": "அவந்து மத₃நாஸிகாமநுஜபஞ்சவக்த்ரஸ்ய மாம்"},
    {"v": 6, "text": "अहम्प्रथमिकामिथःप्रकटिताहवा बाहवः ॥", "lat": "ahamprathamikāmithaḥprakaṭitāhavā bāhavaḥ ||", "tam": "அஹம்ப்ரத₂மிகாமித₂:ப்ரகடிதாஹவா பா₃ஹவ: ॥"},
    {"v": 7, "text": "सटापटलभीषणे सरभसाट्टहासोद्भटे", "lat": "saṭāpaṭalabhīṣaṇē sarabhasāṭṭahāsōdbhaṭē", "tam": "ஸடாபடலபீ₄ஷணே ஸரப₄ஸாட்டஹாஸோத்₃ப₄டே"},
    {"v": 7, "text": "स्फुरत्क्रुधि परिस्फुटद्भ्रुकुटिकेऽपि वक्त्रे कृते ।", "lat": "sphuratkrudhi parisphuṭadbhrukuṭikē’pi vaktrē kṛtē |", "tam": "ஸ்பு₂ரத்க்ருதி₄ பரிஸ்பு₂டத்₃ப்₄ருகுடிகேऽபி வக்த்ரே க்ரு’தே ।"},
    {"v": 7, "text": "कृपा कपटकेसरिन् दनुजडिम्भदत्तस्तना", "lat": "kṛpā kapaṭakēsarin danujaḍimbhadattastanā", "tam": "க்ரு’பா கபடகேஸரிந் த₃நுஜடி₃ம்ப₄த₃த்தஸ்தநா"},
    {"v": 7, "text": "सरोजसदृशा दृशा व्यतिभिषज्य ते व्यज्यते ॥", "lat": "sarōjasadṛśā dṛśā vyatibhiṣajya tē vyajyatē ||", "tam": "ஸரோஜஸத்₃ரு’ஶா த்₃ரு’ஶா வ்யதிபி₄ஷஜ்ய தே வ்யஜ்யதே ॥"},
    {"v": 8, "text": "त्वयि रक्षति रक्षकैः किमन्यैः", "lat": "tvayi rakṣati rakṣakaiḥ kimanyaiḥ", "tam": "த்வயி ரக்ஷதி ரக்ஷகை: கிமந்யை:"},
    {"v": 8, "text": "त्वयि चारक्षति रक्षकैः किमन्यैः ।", "lat": "tvayi cārakṣati rakṣakaiḥ kimanyaiḥ |", "tam": "த்வயி சாரக்ஷதி ரக்ஷகை: கிமந்யை: ।"},
    {"v": 8, "text": "इति निश्चितधीः श्रयामि नित्यं", "lat": "iti niścitadhīḥ śrayāmi nityaṃ", "tam": "இதி நிஶ்சிததீ₄: ஶ்ரயாமி நித்யம்"},
    {"v": 8, "text": "नृहरे वेगवतीतटाश्रयं त्वाम् ॥", "lat": "nṛharē vēgavatītaṭāśrayaṃ tvām ||", "tam": "ந்ரு’ஹரே வேக₃வதீதடாஶ்ரயம் த்வாம் ॥"},
    {"v": 9, "text": "इत्थं स्तुतः सकृदिहाष्टभिरेष पद्यैः", "lat": "itthaṃ stutaḥ sakṛdihāṣṭabhirēṣa padyaiḥ", "tam": "இத்த₂ம் ஸ்துத: ஸக்ரு’தி₃ஹாஷ்டபி₄ரேஷ பத்₃யை:"},
    {"v": 9, "text": "श्रीवेङ्कटेशरचितैस्त्रिदशेन्द्रवन्द्यः ।", "lat": "śrīvēṅkaṭēśaracitaistridaśēndravandyaḥ |", "tam": "ஶ்ரீவேங்கடேஶரசிதைஸ்த்ரித₃ஶேந்த்₃ரவந்த்₃ய: ।"},
    {"v": 9, "text": "दुर्दान्तघोरदुरितद्विरदेन्द्रभेदी", "lat": "durdāntaghōraduritadviradēndrabhēdī", "tam": "து₃ர்தா₃ந்தகோ₄ரது₃ரிதத்₃விரதே₃ந்த்₃ரபே₄தீ₃"},
    {"v": 9, "text": "कामासिकानरहरिर्वितनोतु कामान् ॥", "lat": "kāmāsikānaraharirvitanōtu kāmān ||", "tam": "காமாஸிகாநரஹரிர்விதநோது காமாந் ॥"},
    {"v": 10, "text": "कवितार्किकसिंहाय कल्याणगुणशालिने ।", "lat": "kavitārkikasiṃhāya kalyāṇaguṇaśālinē |", "tam": "கவிதார்கிகஸிம்ஹாய கல்யாணகு₃ணஶாலிநே ।"},
    {"v": 10, "text": "श्रीमते वेङ्कटेशाय वेदान्तगुरवे नमः ॥", "lat": "śrīmatē vēṅkaṭēśāya vēdāntaguravē namaḥ ||", "tam": "ஶ்ரீமதே வேங்கடேஶாய வேதா₃ந்தகு₃ரவே நம: ॥"},
  ],
};
